/**
 * Build the isolated View's theme CSS from the trusted shell's theme registry.
 *
 * This module is Node-side build tooling. The generated bytes are ordinary CSS
 * embedded in the opaque-origin View; the View bundle never imports Dashboard
 * code or gains access to its document, bootstrap payload, or credentials.
 */

import {
  AGENT_VIEW_THEME_PROFILES,
  type AgentViewThemeProfile,
  type AgentViewThemeToken,
} from "@claude-bot/dashboard-web/theme-registry";

const TOKEN_NAME = /^[a-z][a-z0-9-]*$/;
const THEME_ID = /^[a-z][a-z0-9-]*$/;

function isSchemeToken(token: AgentViewThemeToken): token is Extract<AgentViewThemeToken, { light: string }> {
  return "light" in token;
}

function selector(profile: AgentViewThemeProfile): string {
  if (!THEME_ID.test(profile.id)) throw new Error(`invalid Agent View theme id: ${profile.id}`);
  return profile.id === "classic" ? ":root" : `html[data-av-theme="${profile.id}"]`;
}

function declaration(name: string, token: AgentViewThemeToken): string {
  if (!TOKEN_NAME.test(name)) throw new Error(`invalid Agent View token name: ${name}`);
  const value = isSchemeToken(token)
    ? `light-dark(${token.light}, ${token.dark})`
    : token.value;
  return `  --av-${name}: ${value};`;
}

function legacyDeclaration(name: string, token: AgentViewThemeToken): string | null {
  const value = isSchemeToken(token) ? token.light : token.legacyLight;
  return value === undefined ? null : `    --av-${name}: ${value};`;
}

/** Stable bytes folded into every Agent View source digest. */
export const AGENT_VIEW_THEME_SOURCE_BYTES = JSON.stringify(AGENT_VIEW_THEME_PROFILES);

/** Deterministic CSS prepended to every Agent View build. */
export function renderAgentViewThemeCss(
  profiles: readonly AgentViewThemeProfile[] = AGENT_VIEW_THEME_PROFILES,
): string {
  const ids = new Set<string>();
  const blocks: string[] = [
    "/* Generated from @claude-bot/dashboard-web/theme-registry. Do not hand-edit. */",
  ];
  const legacy: string[] = [];

  for (const profile of profiles) {
    if (ids.has(profile.id)) throw new Error(`duplicate Agent View theme id: ${profile.id}`);
    ids.add(profile.id);
    const target = selector(profile);
    const entries = Object.entries(profile.tokens);
    if (!entries.length) throw new Error(`Agent View theme has no tokens: ${profile.id}`);
    blocks.push(`${target} {`, ...entries.map(([name, token]) => declaration(name, token)), "}");

    const fallback = entries
      .map(([name, token]) => legacyDeclaration(name, token))
      .filter((line): line is string => line !== null);
    if (fallback.length) legacy.push(`  ${target} {`, ...fallback, "  }");
  }

  if (!ids.has("classic")) throw new Error("Agent View theme registry must include classic");
  blocks.push(
    "@supports not (color: light-dark(white, black)) {",
    ...legacy,
    "}",
    "",
  );
  return blocks.join("\n");
}
